mapper.insert:
INSERT INTO public."CR_授業転写セグメント情報" (
    "授業記録ID", "連番", "開始オフセット秒", "終了オフセット秒", "話者ラベル",
    "発話キー", "音源", "原文テキスト", "言語"
) VALUES (
    #{recordId}, #{seq}, #{startOffsetSeconds}, #{endOffsetSeconds}, #{speaker},
    #{utteranceKey}, #{source}, #{text}, #{language}
)

mapper.select:
SELECT "転写セグメントID", "授業記録ID", "連番", "開始オフセット秒", "終了オフセット秒",
       "話者ラベル", "発話キー", "音源", "原文テキスト", "言語", "登録日時"
  FROM public."CR_授業転写セグメント情報"
 WHERE "授業記録ID" = #{recordId}
   AND "発話キー" = #{utteranceKey}

mapper.update:
UPDATE public."CR_授業転写セグメント情報"
   SET "開始オフセット秒" = #{startOffsetSeconds},
       "終了オフセット秒" = #{endOffsetSeconds},
       "原文テキスト" = #{text},
       "言語" = #{language}
 WHERE "転写セグメントID" = #{segmentId}

mapper.select:
SELECT COALESCE(MAX("連番"), 0)
  FROM public."CR_授業転写セグメント情報"
 WHERE "授業記録ID" = #{recordId}

SELECT "転写セグメントID", "授業記録ID", "連番", "開始オフセット秒", "終了オフセット秒",
       "話者ラベル", "発話キー", "音源", "原文テキスト", "言語", "登録日時"
  FROM public."CR_授業転写セグメント情報"
 WHERE "授業記録ID" = #{recordId}
   AND "連番" > #{afterSeq}
 ORDER BY "連番"
